#!/usr/bin/env python3
from pathlib import Path
import importlib.util
import sys

ROOT = Path(sys.argv[1]).resolve() if len(sys.argv) > 1 else Path(__file__).resolve().parents[1]
PATCH = ROOT / 'web' / 'fix_v311_mobile_hub_clean_pass.py'
spec = importlib.util.spec_from_file_location('v311_gamebar_runtime', PATCH)
mod = importlib.util.module_from_spec(spec)
spec.loader.exec_module(mod)

# Exact shape generated by V154 before V286/V302: Home and Hub do not carry
# data-active attributes; Shorts/Drafts/Social do. V302 only replaces Social
# with Live, so V311 must support this actual production shape.
runtime_shell = '''
<style>.gsf-page-gamebar-inner{grid-template-columns:repeat(5,minmax(0,1fr))}</style>
<nav id="gsf-page-nav-v249" aria-label="Navigazione pagina">
  <button class="gsf-page-nav-item" data-target="home" type="button"><svg></svg><span>Home</span></button>
  <button class="gsf-page-nav-item" data-target="hub" data-section="dashboard" type="button"><svg></svg><span>Hub</span></button>
  <button class="gsf-page-nav-item" data-target="hub" data-section="shorts" data-active="shorts" type="button"><svg></svg><span>I miei Shorts</span></button>
  <button class="gsf-page-nav-item" data-target="hub" data-section="drafts" data-active="drafts" type="button"><svg></svg><span>Bozze</span></button>
  <button class="gsf-page-nav-item" data-target="hub" data-section="live" data-active="live" type="button"><svg></svg><span>Live</span></button>
</nav>
<script>
if(activeKey==='drafts') active=(lastTarget==='hub'&&lastSection==='drafts');
else if(activeKey==='shorts') active=(lastTarget==='hub'&&lastSection==='shorts');
else if(activeKey==='live') active=(lastTarget==='hub'&&lastSection==='live');
else if(target==='hub') active=(lastTarget==='hub'&&lastSection!=='drafts'&&lastSection!=='shorts'&&lastSection!=='live');
else active=(lastTarget===target);
const hubUrl="/creator-hub-v156/?v=307";
</script>
'''

try:
    patched = mod.patch_shell_text(runtime_shell)
except Exception as exc:
    raise SystemExit(f'V311.4 production Game Bar regression: {exc}') from exc

required = (
    'data-target="hub" data-section="dashboard" data-active="home"',
    '<span>Home</span>',
    'data-target="hub" data-section="dashboard" type="button"',
    '<span>Hub</span>',
    'data-target="hub" data-section="projects" data-active="projects"',
    '<span>Progetti</span>',
    'data-target="hub" data-section="live" data-active="live"',
    '<span>Live</span>',
    '/creator-hub-v156/?v=3114',
)
for marker in required:
    if marker not in patched:
        raise SystemExit('V311.4 production Game Bar missing: ' + marker)
if patched.count('class="gsf-page-nav-item"') != 4:
    raise SystemExit('V311.4 production Game Bar must contain exactly four buttons')
if '<span>I miei Shorts</span>' in patched or '<span>Bozze</span>' in patched:
    raise SystemExit('V311.4 production Game Bar still contains legacy Shorts/Bozze buttons')
if mod.patch_shell_text(patched) != patched:
    raise SystemExit('V311.4 production Game Bar normalization is not idempotent')

print('V311.4 production Game Bar shape: PASS')
